args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?director ?directorLabel ?deathDate WHERE {
  VALUES ?film { <http://dbpedia.org/resource/Youngblood_Hawke_(film)> <http://dbpedia.org/resource/Crook's_Tour> }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:deathDate ?d1. }
  OPTIONAL { ?director dbp:deathDate ?d2. }
  BIND(coalesce(?d1, ?d2) AS ?deathDate)
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en') }
}
ORDER BY ?film

